PAGINA_EMBASA = "https://www.embasa.ba.gov.br/2026.11"


def cadastrar_embasa(apps, schema_editor):
    """Cadastra o endereço da EMBASA — a única fonte cujo endereço é do código.

    As demais são cadastradas pelo dono da plataforma, e é assim por decisão da
    ORC.8: a URL da Caixa já mudou uma vez, e o conserto tem de ser uma caixa de
    texto. A EMBASA é diferente em duas coisas que juntas justificam a semente:
    o endereço não é template de mês (é a página do semestre, com nome próprio),
    e o motor já precisa conhecê-lo para listar os documentos. Deixá-lo só no
    código e não no banco faria a tela pedir um cadastro que ninguém sabe qual é.

    `dia_do_mes = 0` de propósito: a varredura mensal não dispara esta fonte
    (`carga.exige_escolha_de_documento`), porque escolher uma das 65 tabelas por
    alguém é escolher o preço de uma região para quem orça em outra.
    """
    FonteOficial = apps.get_model("moduloorcamento", "FonteOficial")
    FonteOficial.objects.get_or_create(
        fonte="embasa",
        defaults={
            "template_url": PAGINA_EMBASA,
            "pagina_referencia": PAGINA_EMBASA,
            "ativa": True,
            "dia_do_mes": 0,
            "defasagem_meses": 2,
            "observacao": (
                "Tabela de preços de saneamento da Bahia, publicada por SEMESTRE e "
                "só em PDF. O endereço acima é a PÁGINA do semestre, não um arquivo: "
                "a carga lista os documentos dela e carrega o que for escolhido, um "
                "por corrida. Quando a EMBASA abrir o semestre seguinte, é esta URL "
                "que muda."
            ),
        },
    )


def descadastrar_embasa(apps, schema_editor):
    FonteOficial = apps.get_model("moduloorcamento", "FonteOficial")
    FonteOficial.objects.filter(fonte="embasa", template_url=PAGINA_EMBASA).delete()


